function MilestoneIcon({ kind }: { kind: string }) {
  const icons: Record<string, ReactNode> = {
    bot: <><rect x="5" y="8" width="14" height="11" rx="2.5"/><path d="M12 4v4M9 12h.01M15 12h.01M9 16h6M3 11v5M21 11v5"/></>,
    lock: <><rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 1 1 8 0v3"/></>,
    file: <><path d="M6 3.5h8l4 4V20H6z"/><path d="M14 3.5V8h4M9 12h6M9 16h6"/></>,
    wallet: <><path d="M5 6h13a2 2 0 0 1 2 2v12H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2Z"/><path d="M3.5 8H18M15 13h5v4h-5a2 2 0 0 1 0-4Z"/><path d="M16.5 15h.01"/></>,
    shield: <><path d="m12 3 8 3v5.5c0 4.5-3.3 7.8-8 9.5-4.7-1.7-8-5-8-9.5V6z"/></>,
    users: <><circle cx="9" cy="8" r="3"/><path d="M3.5 20v-1.5a5.5 5.5 0 0 1 11 0V20M16 5.5a3 3 0 0 1 0 5.8M17 14a4.5 4.5 0 0 1 3.5 4.4V20"/></>,
  };
  const icon = icons[kind] ?? <><circle cx="12" cy="12" r="8"/></>;
  return <svg className="aw-feature-icon-svg" viewBox="0 0 24 24" fill="none" aria-hidden="true">{icon}</svg>;
}

export function LandingScreen({ onStart }: { onStart: () => void }) {
  const lang = useLang();
  const steps = [
    ["bot", "Chat with AI", "Describe the job, e.g. “Hire a logo designer, ฿5,000, 2 milestones”. The AI drafts the deal."],
    ["lock", "Bank locks the money", "Your bank is debited only when you approve the deal, one milestone at a time."],
    ["file", "Deliver & review", "Files are encrypted in the browser. Review, then approve each milestone."],
    ["wallet", "Paid to the seller’s bank", "Released straight to their bank account. THB ↔ CNY at a fixed rate."],
  ];
  const security = [
    ["shield", "Two layers of protection", "Policy checks before anything happens, then contract rules that enforce limits and the allowlist.", "violet"],
    ["users", "Disputes settled by AI", "AI mediator first, then 3 independent models (2 of 3 must agree), appeal to 5.", "blue"],
    ["lock", "Your data, your control", "PDPA: delete your data anytime. Only fingerprints (hashes) are kept as evidence.", "green"],
  ];
  const faqs = [
    ["Do I need crypto or a wallet?", "No. You log in with your bank. Everything is shown in baht or yuan."],
    ["Can I top up or withdraw?", "No. Money stays in your bank until a deal is locked, so there is nothing to top up or withdraw."],
    ["What if the bank is debited and something fails?", "The system rolls back automatically and refunds the debit. Every debit has an idempotency key, so retries never charge twice."],
    ["Who decides a dispute?", "AI models from different providers, each signing separately. No single party controls the verdict."],
  ];
  return localizeMockupNode(<main className="aw-landing aw-landing-milestone"><div className="aw-milestone-wrap"><section className="aw-milestone-hero"><span className="aw-demo-pill">Demo · Mock Bank · no real money</span><h1>Hire and get paid safely, with<br className="aw-desktop-break" /> AI in the middle</h1><p>Your money stays in your own bank account. It is debited only when a deal is locked, and paid to the seller when the work is approved.<br />No crypto, no top-ups, no withdrawals.</p><div className="aw-milestone-cta"><Button onClick={onStart}><svg className="aw-bank-lock-icon" viewBox="0 0 16 16" fill="none" aria-hidden="true"><rect x="3" y="7" width="10" height="7" rx="1.5" /><path d="M5.5 7V5a2.5 2.5 0 0 1 5 0v2M8 9.5v2" /></svg>Log in with your bank</Button><a className="aw-how-button" href="#how-it-works">How it works</a></div><small>Log in required to chat with the AI and start a deal</small></section>
    <section className="aw-milestone-section" id="how-it-works"><small className="aw-section-kicker">HOW IT WORKS</small><h2>Four steps, all in your bank</h2><div className="aw-grid aw-grid-4 aw-milestone-cards">{steps.map(([icon,title,body],i)=><article className="aw-milestone-card" key={title}><div className={`aw-milestone-icon aw-icon-${icon}`}><MilestoneIcon kind={icon}/></div><small className="aw-step-index">0{i+1}</small><b>{title}</b><p>{body}</p></article>)}</div></section>
    <section className="aw-milestone-section" id="security"><small className="aw-section-kicker">SECURITY</small><h2>Built for safety</h2><div className="aw-grid aw-grid-3 aw-milestone-cards">{security.map(([icon,title,body,tone])=><article className="aw-milestone-card aw-security-card" key={title}><div className={`aw-milestone-icon aw-icon-${tone}`}><MilestoneIcon kind={icon}/></div><b>{title}</b><p>{body}</p></article>)}</div></section>
    <section className="aw-milestone-section" id="accounts"><small className="aw-section-kicker">ACCOUNTS</small><h2>For people and companies</h2><div className="aw-grid aw-grid-2 aw-milestone-cards"><article className="aw-milestone-card aw-account-card"><b><i className="aw-dot aw-dot-violet" />Personal account</b><p>Pay and get paid from your own bank account.</p></article><article className="aw-milestone-card aw-account-card"><b><i className="aw-dot aw-dot-blue" />Company account</b><p>Group wallets and team approvals pay from the company account.</p></article></div></section>
    <section className="aw-milestone-section aw-faq-section" id="faq"><small className="aw-section-kicker">FAQ</small><h2>Questions</h2><div className="aw-faq-list">{faqs.map(([question,answer])=><details key={question} open><summary>{question}<span>−</span></summary><p>{answer}</p></details>)}</div></section><footer className="aw-milestone-footer"><span>Demo build · Mock Bank is not a real bank</span><span>© 2026 MilestonePay</span></footer></div></main>, lang);
}

export type BankChoice = "thai" | "chinese";

export function LoginScreen({ onAuthorize, initialBank = "thai" }: { onAuthorize: (bank: BankChoice) => void; initialBank?: BankChoice }) {
  const [bank, setBank] = useState<BankChoice>(initialBank);
  const [consent, setConsent] = useState(true);
  const lang = useLang();
  return localizeMockupNode(<main className="aw-auth-wrap aw-bank-login-wrap"><Card className="aw-bank-login"><h2>Log in to continue</h2><div className="aw-login-warning"><span>!</span>You need to log in before using AI Chat, deals or groups.</div><small className="aw-bank-label">Choose your bank</small><div className="aw-bank-options" role="radiogroup" aria-label="Choose your bank"><button type="button" role="radio" aria-checked={bank === "thai"} className={`aw-bank-option${bank === "thai" ? " selected" : ""}`} onClick={() => setBank("thai")}><span className="aw-bank-code aw-bank-th">TH</span><span className="aw-bank-copy"><b>Thai bank</b><small>Mock Bank · Thailand · THB</small></span><span className="aw-radio-dot" /></button><button type="button" role="radio" aria-checked={bank === "chinese"} className={`aw-bank-option${bank === "chinese" ? " selected" : ""}`} onClick={() => setBank("chinese")}><span className="aw-bank-code aw-bank-cn">CN</span><span className="aw-bank-copy"><b>Chinese bank</b><small>Mock Bank · China · CNY</small></span><span className="aw-radio-dot" /></button></div><Button className="aw-bank-continue" onClick={() => onAuthorize(bank)} disabled={!consent}><svg className="aw-bank-lock-icon" viewBox="0 0 16 16" fill="none" aria-hidden="true"><rect x="3" y="7" width="10" height="7" rx="1.5" /><path d="M5.5 7V5a2.5 2.5 0 0 1 5 0v2M8 9.5v2" /></svg>Continue with {bank === "thai" ? "Thai" : "Chinese"} bank</Button><div className="aw-bank-demo"><span>Demo bank</span><small>Not a real bank account</small></div><hr /><label className="aw-bank-consent"><input type="checkbox" checked={consent} onChange={(event) => setConsent(event.target.checked)} /><span>I agree to the Privacy Policy (PDPA) and allow personal data to be removed before messages reach the AI.</span></label><p className="aw-bank-footnote">You can only link passbooks from the bank you choose here. New here? Logging in creates your account and your AI agent automatically.</p></Card></main>, lang);
}

