export function SummaryScreen() {
  const lang = useLang();
  const [period, setPeriod] = useState("30 days");
  const [activity, setActivity] = useState("All");
  const rows = [
    { date: "14 Oct 10:41", description: "Lock · Logo design M1", type: "Debit", deal: "D-021", account: "Personal ··4821", amount: "−฿2,500.00", detail: "≈ ¥510.20 to Lin" },
    { date: "13 Oct 16:05", description: "Paid · P&ID drawing set", type: "Credit", deal: "D-015", account: "Company ··9033", amount: "+฿9,000.00" },
    { date: "12 Oct 09:30", description: "Lock · CAD drawings", type: "Debit", deal: "D-014", account: "Personal ··4821", amount: "−฿4,000.00" },
    { date: "10 Oct 11:12", description: "Timeout refund · Wiring check", type: "Refund", deal: "D-011", account: "Personal ··4821", amount: "+฿1,200.00" },
    { date: "08 Oct 14:20", description: "Lock · 3D model set", type: "Debit", deal: "D-012", account: "Personal ··4821", amount: "−฿16,000.00" },
  ];
  const visibleRows = rows.filter((row) => activity === "All" || row.type === activity);
  const bars = [["May", 18, 27], ["Jun", 27, 38], ["Jul", 13, 52], ["Aug", 37, 43], ["Sep", 22, 88], ["Oct", 39, 105]];
  const exportCsv = () => {
    const csv = ["Date,Description,Type,Deal,Bank account,Amount", ...visibleRows.map((r) => [r.date, r.description, r.type, r.deal, r.account, r.amount].map((v) => `"${v.replaceAll('"', '""')}"`).join(","))].join("\n");
    const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
    const link = document.createElement("a"); link.href = url; link.download = "milestonepay-bank-activity.csv"; link.click(); URL.revokeObjectURL(url);
  };
  return localizeMockupNode(<div className="aw-summary-page"><div className="aw-ai-balancebar"><div className="aw-ai-bank"><span className="aw-ai-wallet-icon"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 6h13a2 2 0 0 1 2 2v12H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2Z"/><path d="M3 8h15M15 13h5v4h-5a2 2 0 0 1 0-4Z"/></svg></span><span><small>Thai bank · passbook ··4821</small><b>฿48,250.00 <i>Available</i></b></span></div><div className="aw-ai-balance-stat"><small>Locked in deals</small><b>฿7,500.00</b></div><div className="aw-ai-balance-stat"><small>Fixed rate</small><b>¥1 = ฿4.90</b></div><div className="aw-ai-balance-actions"><span className="aw-no-topup">× No top-up / withdraw</span><span className="aw-demo-bank-pill">Demo bank</span></div></div><main className="aw-summary-content"><header className="aw-summary-heading"><div><h1>Summary</h1><p>Money in and out of your bank accounts, explained by AI</p></div><div className="aw-summary-controls"><div className="aw-summary-period">{["7 days", "30 days", "90 days", "All"].map((option) => <button key={option} className={period === option ? "active" : ""} onClick={() => setPeriod(option)}>{option}</button>)}</div><Button onClick={exportCsv}><span aria-hidden="true">⇩</span> Export CSV</Button></div></header><div className="aw-summary-metrics">{[["↓", "Received", "฿9,000.00", "1 deal sold · paid to company ··9033", "green"], ["↑", "Spent", "฿26,500.00", "Debited for 4 milestones", "red"], ["♙", "Locked now", "฿7,500.00", "In 2 active deals", "yellow"], ["✓", "Refunded", "฿1,200.00", "1 timeout refund", "blue"]].map(([icon, label, amount, detail, tone]) => <article className="aw-summary-metric" key={label}><div><span className={`aw-summary-metric-icon ${tone}`}>{label === "Received" ? <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 4v15M5 12l7 7 7-7"/></svg> : label === "Spent" ? <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 20V5M5 12l7-7 7 7"/></svg> : label === "Locked now" ? <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg> : <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m5 12 4.5 4.5L19 7"/></svg>}</span><small>{label}</small></div><b className={tone}>{amount}</b><p>{detail}</p></article>)}</div><section className="aw-summary-ai"><div className="aw-summary-ai-head"><b><span><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 4V2.5M9.5 2.5h5"/><rect x="5" y="7" width="14" height="12" rx="2.5"/><path d="M3 10v6M21 10v6M9 11h.01M15 11h.01M9 15h6"/></svg></span> AI summary · October</b><small>Reads totals only</small></div><p>You spent ฿26,500 across 4 deals this month, 62% of it on engineering drawings. ฿7,500 is still locked and will either be paid out or refunded. If the D-012 appeal holds, ฿11,200 comes back to your bank.</p><div><span>Spending ↑ 18% vs September</span><span>No failed debits</span><span>1 refund</span></div></section><section className="aw-summary-chart"><header><b>Received vs spent · 6 months (฿ thousand)</b><span><i className="green-dot"/> Received <i className="red-dot"/> Spent</span></header><div className="aw-summary-bars">{bars.map(([month, received, spent]) => <div className="aw-summary-bar-group" key={month}><div className="aw-summary-bars-pair"><i style={{ height: `${received}px` }}/><i style={{ height: `${spent}px` }}/></div><small>{month}</small></div>)}</div></section><section className="aw-summary-activity"><header><b>Bank activity</b><div>{["All", "Debits", "Credits", "Refunds"].map((type) => <button key={type} className={activity === (type === "Debits" ? "Debit" : type === "Credits" ? "Credit" : type === "Refunds" ? "Refund" : "All") ? "active" : ""} onClick={() => setActivity(type === "Debits" ? "Debit" : type === "Credits" ? "Credit" : type === "Refunds" ? "Refund" : "All")}>{type}</button>)}</div></header><div className="aw-summary-table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Type</th><th>Deal</th><th>Bank account</th><th>Amount</th></tr></thead><tbody>{visibleRows.map((row) => <tr key={row.deal}><td>{row.date}</td><td><b>{row.description}</b></td><td><span className={`aw-summary-type ${row.type.toLowerCase()}`}>{row.type}</span></td><td><code>{row.deal}</code></td><td>{row.account}</td><td className={row.type === "Debit" ? "debit" : "credit"}><b>{row.amount}</b>{row.detail && <small>{row.detail}</small>}</td></tr>)}</tbody></table></div></section></main></div>, lang);
}

