function CreateGroupScreen({ onCancel, onCreate }: { onCancel: () => void; onCreate: (name: string, selected: string[], passbook: string) => void }) {
  const lang = useLang();
  const [name, setName] = useState("PLC Team");
  const [description, setDescription] = useState("Share CAD and ladder files inside the team and pay contractors together");
  const [passbook, setPassbook] = useState("company");
  const [rule, setRule] = useState("2 of 3 members");
  const [perPayment, setPerPayment] = useState("฿10,000");
  const [perDay, setPerDay] = useState("฿30,000");
  const [aiPropose, setAiPropose] = useState(true);
  const [validity, setValidity] = useState("7 days");
  const [selected, setSelected] = useState(["Somchai A.", "Nok Engineering", "Wanchai Design"]);
  const [qrVersion, setQrVersion] = useState(0);
  const [saved, setSaved] = useState(false);
  const qrPattern = ["1110101110111", "1011101010101", "1110101110111", "0001010001000", "1101010110110", "0110101001101", "1011110101010", "1110001011101", "1011011110010", "0110100101110", "1110101110101", "1011010001110", "1110101110111"];
  const members = [{ name: "Somchai A.", initials: "SA", role: "Signer", color: "blue" }, { name: "Nok Engineering", initials: "N", role: "Signer", color: "green" }, { name: "Wanchai Design", initials: "W", role: "Member", color: "yellow" }, { name: "Non", initials: "N", role: "Member", color: "red" }];
  const downloadQr = () => {
    const cell = 16;
    const rects = qrPattern.flatMap((row, y) => row.split("").flatMap((bit, x) => bit === "1" ? [`<rect x="${x * cell}" y="${y * cell}" width="${cell}" height="${cell}"/>`] : [] )).join("");
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${cell * 13}" height="${cell * 13}" viewBox="0 0 ${cell * 13} ${cell * 13}"><rect width="100%" height="100%" fill="white"/><g fill="black">${rects}</g></svg>`;
    const url = URL.createObjectURL(new Blob([svg], { type: "image/svg+xml" })); const link = document.createElement("a"); link.href = url; link.download = `${name || "group"}-invite.svg`; link.click(); URL.revokeObjectURL(url); setSaved(true);
  };
  const submit = (event: FormEvent) => { event.preventDefault(); if (name.trim()) onCreate(name.trim(), selected, passbook); };
  return localizeMockupNode(<div className="aw-create-group-content"><header className="aw-create-group-heading"><h1>Create group</h1><button type="button" onClick={onCancel}>← Groups</button></header><div className="aw-create-group-layout"><form className="aw-create-details" id="create-group-form" onSubmit={submit}><h2>Group details</h2><label className="aw-create-field">Group name<input value={name} onChange={(event) => setName(event.target.value)}/></label><label className="aw-create-field">Description<textarea value={description} onChange={(event) => setDescription(event.target.value)}/></label><div className="aw-create-private"><svg viewBox="0 0 18 18" fill="none" aria-hidden="true"><rect x="3" y="8" width="12" height="8" rx="1.5"/><path d="M5.5 8V5.5a3.5 3.5 0 0 1 7 0V8"/></svg>Private group · people can join only by scanning your invitation QR</div><hr/><h3>Group pays from</h3><p className="aw-create-help">Payments are debited from this passbook only after members approve. There is no group top-up.</p><div className={`aw-passbook-option ${passbook === "personal" ? "selected" : ""}`} role="radio" aria-checked={passbook === "personal"} tabIndex={0} onClick={() => setPassbook("personal")}><span className="aw-radio-dot"/><div><b>Savings passbook ··4821 <em>Personal</em></b><small>Gun · Savings · THB</small></div><strong>฿48,250.00</strong></div><div className={`aw-passbook-option ${passbook === "company" ? "selected" : ""}`} role="radio" aria-checked={passbook === "company"} tabIndex={0} onClick={() => setPassbook("company")}><span className="aw-radio-dot"/><div><b>Current passbook ··9033 <em className="company">Company</em></b><small>Gun Studio Co., Ltd. · Current · THB</small></div><strong>฿310,400.00</strong></div><hr/><div className="aw-create-limits"><label>Approval rule<select value={rule} onChange={(event) => setRule(event.target.value)}><option>2 of 3 members</option><option>All members</option><option>1 of 2 members</option></select></label><label>Per payment limit<input value={perPayment} onChange={(event) => setPerPayment(event.target.value)}/></label><label>Per day limit<input value={perDay} onChange={(event) => setPerDay(event.target.value)}/></label></div><div className="aw-create-ai-toggle"><span><b>Let the group AI propose payments</b><small>Members still approve every payment</small></span><button type="button" role="switch" aria-checked={aiPropose} className={aiPropose ? "on" : ""} onClick={() => setAiPropose((value) => !value)}><i/></button></div></form><aside className="aw-create-invite"><h2>Invite members</h2><div className="aw-create-qr-card"><div className="aw-create-qr" data-version={qrVersion}>{qrPattern.flatMap((row, y) => row.split("").map((bit, x) => <i key={`${y}-${x}`} className={bit === "1" ? "on" : ""}/>))}</div><b>Scan to join {name || "your group"}</b><div><span>Private · invite only</span><span>Valid until 21 Oct 2026</span></div></div><div className="aw-qr-valid"><b>QR valid for</b><small>min 3 days · max 2 weeks</small></div><div className="aw-qr-validity">{["3 days", "5 days", "7 days", "10 days", "14 days"].map((option) => <button type="button" key={option} className={validity === option ? "active" : ""} onClick={() => {setValidity(option);setQrVersion((version) => version + 1);setSaved(false);}}>{option}</button>)}</div><p className="aw-qr-expiry">Regenerating the QR makes the old one stop working immediately.</p><div className="aw-qr-actions"><Button type="button" variant="outline" onClick={() => {setQrVersion((version) => version + 1);setSaved(false);}}>▦ &nbsp;Regenerate QR</Button><Button type="button" variant="outline" onClick={downloadQr}>▦ &nbsp;{saved ? "QR saved" : "Save QR"}</Button></div><div className="aw-invite-friends-head"><b>Invite from friends</b><span>{selected.length} selected</span></div><div className="aw-invite-friend-list">{members.map((member) => <label key={member.name}><span className={`aw-friend-avatar ${member.color}`}>{member.initials}</span><span><b>{member.name}</b><small>{member.role}</small></span><input type="checkbox" checked={selected.includes(member.name)} onChange={(event) => setSelected((current) => event.target.checked ? [...current, member.name] : current.filter((person) => person !== member.name))}/></label>)}</div><Button type="submit" form="create-group-form" className="aw-create-group-submit">Create group &amp; send invites</Button></aside></div></div>, lang);
}

